SELECT c.chunk_id, c.file_id, f.file_name, c.chunk_index, c.chunk_text, c.chunk_length, c.created_at FROM text_chunk c LEFT JOIN file_metadata f ON f.id = c.file_id JOIN ( VALUES
(#{id}, #{idx})
) AS t(chunk_id, sort_order) ON c.chunk_id = t.chunk_id ORDER BY t.sort_order

SELECT c.chunk_id, c.file_id, c.chunk_index, c.chunk_text, c.chunk_length, c.start_offset, c.end_offset, c.status, c.created_at, c.updated_at FROM text_chunk c JOIN ( VALUES
(#{id}, #{idx})
) AS t(chunk_id, sort_order) ON c.chunk_id = t.chunk_id ORDER BY t.sort_order
